"""AC-6 / G5-for-other-environments comparator (DEP-LOCK-AT WU-2, ADR-065).

Every guard in ``scripts/ci/check_freeze_matches_lock.py`` has a test here that
goes RED when the guard is removed (the neuter is named in each docstring).
"""

from __future__ import annotations

import io
import json
import subprocess
import sys
from pathlib import Path

import pytest

from scripts.ci import check_freeze_matches_lock as mod

REPO_ROOT = Path(__file__).resolve().parent.parent
SHA = "a" * 40
LOCK = f"""\
# autogenerated
#    uv pip compile x --python-version 3.12
alpha==1.0 \\
    --hash=sha256:{"0" * 64}
beta==2.0 ; sys_platform == 'win32' \\
    --hash=sha256:{"1" * 64}
Gamma_Pkg==3.0 \\
    --hash=sha256:{"2" * 64}
"""
PYPROJECT = f'deps = ["audittrace-object-storage @ git+https://x/audittrace-object-storage.git@{SHA}"]\n'
GOOD = "alpha==1.0\ngamma-pkg==3.0\n"


def run(freeze: str = GOOD, **kw: object) -> list[str]:
    return mod.check(LOCK, freeze, **kw)  # type: ignore[arg-type]


def test_an_environment_equal_to_the_lock_has_no_violations() -> None:
    assert run() == []


def test_a_wrong_version_is_flagged() -> None:
    """Neuter: drop the version compare -> RED."""
    assert any(
        "alpha: installed 1.1, lock pins 1.0" in p
        for p in run("alpha==1.1\ngamma-pkg==3.0\n")
    )


def test_a_missing_pin_is_flagged() -> None:
    assert any(
        "gamma-pkg==3.0 is in the lock but NOT installed" in p
        for p in run("alpha==1.0\n")
    )


def test_an_extra_package_is_flagged_unless_allowed() -> None:
    """Neuter: drop the extras sweep -> RED."""
    assert any(
        "rogue==9 is installed but NOT in the lock" in p
        for p in run(GOOD + "rogue==9\n")
    )
    assert run(GOOD + "rogue==9\n", allow_extra=["Rogue"]) == []


def test_a_marker_that_does_not_apply_is_not_required_and_one_that_does_is() -> None:
    """beta is win32-only: absent on linux is fine, present is 'not in the lock'."""
    assert run(marker_env={"sys_platform": "linux"}) == []
    assert any(
        "beta==2.0 is in the lock but NOT installed" in p
        for p in run(marker_env={"sys_platform": "win32"})
    )


def test_the_marker_environment_of_the_target_decides_not_the_hosts() -> None:
    """Neuter: ignore marker_env (evaluate on the host) -> RED on a win32 target."""
    host_missing_beta = run(marker_env={"sys_platform": "win32"})
    assert host_missing_beta != []


def test_an_unparseable_marker_fails_closed() -> None:
    lock = LOCK.replace("sys_platform == 'win32'", "this is ((not a marker")
    assert any(
        "beta==2.0 is in the lock but NOT installed" in p for p in mod.check(lock, GOOD)
    )


def test_an_unparseable_freeze_line_is_a_violation_not_skipped() -> None:
    """Neuter: skip lines that do not match -> RED (an editable '-e' line hides a package)."""
    problems = run(GOOD + "-e git+https://x/y.git#egg=y\n")
    assert any("unparseable freeze line" in p and "-e git+" in p for p in problems)


def test_a_lock_pin_installed_as_a_direct_reference_is_flagged() -> None:
    problems = run("alpha @ file:///build\ngamma-pkg==3.0\n")
    assert any("alpha: installed as a direct reference" in p for p in problems)


def test_comments_and_blank_lines_in_a_freeze_are_ignored() -> None:
    assert run("\n# hi\n" + GOOD) == []


def test_the_vcs_package_must_be_the_pyproject_sha() -> None:
    """Neuter: drop _check_vcs -> RED."""
    ok = (
        GOOD
        + f"audittrace-object-storage @ git+https://x/audittrace-object-storage.git@{SHA}\n"
    )
    kw = dict(
        allow_extra=["audittrace-object-storage"],
        vcs_package="audittrace-object-storage",
        pyproject_text=PYPROJECT,
    )
    assert run(ok, **kw) == []
    other = ok.replace(SHA, "b" * 40)
    assert any("pyproject pins commit" in p for p in run(other, **kw))


def test_the_vcs_package_must_be_installed_as_a_git_reference() -> None:
    kw = dict(
        allow_extra=["audittrace-object-storage"],
        vcs_package="audittrace-object-storage",
        pyproject_text=PYPROJECT,
    )
    assert any("not installed as a git reference" in p for p in run(GOOD, **kw))
    assert any(
        "not installed as a git reference" in p
        for p in run(GOOD + "audittrace-object-storage==1\n", **kw)
    )


def test_a_pyproject_without_the_sha_is_flagged() -> None:
    kw = dict(
        allow_extra=["audittrace-object-storage"],
        vcs_package="audittrace-object-storage",
        pyproject_text="x = 1\n",
    )
    assert any("no 40-hex" in p for p in run(GOOD, **kw))


# ---- main(): sources and exit codes -------------------------------------------------


def _write(tmp: Path, name: str, text: str) -> Path:
    p = tmp / name
    p.write_text(text)
    return p


def test_main_passes_and_fails_with_the_right_exit_codes(
    tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    lock = _write(tmp_path, "lock.txt", LOCK)
    good = _write(tmp_path, "good", GOOD)
    bad = _write(tmp_path, "bad", "alpha==9\n")
    assert mod.main(["--lock", str(lock), "--freeze", str(good), "--label", "img"]) == 0
    assert "img == " in capsys.readouterr().out
    assert mod.main(["--lock", str(lock), "--freeze", str(bad), "--label", "img"]) == 1
    err = capsys.readouterr().err
    assert "img is NOT" in err and "alpha: installed 9" in err


def test_main_truncates_a_long_problem_list(
    tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    lock = _write(tmp_path, "lock.txt", LOCK)
    many = _write(tmp_path, "many", "".join(f"x{i}==1\n" for i in range(60)))
    assert mod.main(["--lock", str(lock), "--freeze", str(many)]) == 1
    assert "and " in capsys.readouterr().err


def test_main_reads_the_marker_env_file_and_stdin(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    lock = _write(tmp_path, "lock.txt", LOCK)
    env = _write(tmp_path, "env.json", json.dumps({"sys_platform": "win32"}))
    monkeypatch.setattr(sys, "stdin", io.StringIO(GOOD))
    assert (
        mod.main(["--lock", str(lock), "--freeze", "-", "--marker-env", str(env)]) == 1
    )  # beta now required


def test_main_checks_the_vcs_package_with_the_pyproject(tmp_path: Path) -> None:
    lock = _write(tmp_path, "lock.txt", LOCK)
    pp = _write(tmp_path, "pyproject.toml", PYPROJECT)
    fr = _write(
        tmp_path,
        "fr",
        GOOD + f"audittrace-object-storage @ git+https://x/y.git@{SHA}\n",
    )
    args = [
        "--lock",
        str(lock),
        "--freeze",
        str(fr),
        "--allow-extra",
        "audittrace-object-storage",
        "--vcs-package",
        "audittrace-object-storage",
        "--pyproject",
        str(pp),
    ]
    assert mod.main(args) == 0


def _git_repo_with_lock(tmp_path: Path, text: str) -> Path:
    subprocess.run(["git", "init", "-q"], cwd=tmp_path, check=True)
    (tmp_path / "lock.txt").write_text(text)
    subprocess.run(["git", "add", "lock.txt"], cwd=tmp_path, check=True)
    subprocess.run(
        [
            "git",
            "-c",
            "user.email=t@t.invalid",
            "-c",
            "user.name=t",
            "commit",
            "-qm",
            "x",
        ],
        cwd=tmp_path,
        check=True,
    )
    return tmp_path


def test_lock_rev_reads_the_committed_bytes_not_the_working_tree(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Neuter: read the working-tree file instead of `git show` -> RED (a dirty
    lock would make a drifted image pass)."""
    repo = _git_repo_with_lock(tmp_path, LOCK)
    (repo / "lock.txt").write_text(LOCK.replace("alpha==1.0", "alpha==7.0"))  # dirty
    fr = _write(tmp_path, "fr", GOOD)
    monkeypatch.chdir(repo)
    assert mod.main(["--lock-rev", "HEAD:lock.txt", "--freeze", str(fr)]) == 0


def test_a_failed_git_show_fails_closed(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    repo = _git_repo_with_lock(tmp_path, LOCK)
    fr = _write(tmp_path, "fr", GOOD)
    monkeypatch.chdir(repo)
    with pytest.raises(SystemExit, match="git show HEAD:nope.txt failed"):
        mod.main(["--lock-rev", "HEAD:nope.txt", "--freeze", str(fr)])


def test_python_mode_runs_the_freeze_listing_of_that_interpreter(
    tmp_path: Path,
) -> None:
    lock = _write(tmp_path, "lock.txt", LOCK)
    fake = tmp_path / "py"
    fake.write_text("#!/usr/bin/env bash\necho alpha==1.0\necho gamma-pkg==3.0\n")
    fake.chmod(0o755)
    assert mod.main(["--lock", str(lock), "--python", str(fake)]) == 0
    fake.write_text("#!/usr/bin/env bash\necho boom >&2\nexit 3\n")
    with pytest.raises(SystemExit, match="freeze listing failed"):
        mod.main(["--lock", str(lock), "--python", str(fake)])


def test_the_real_lock_parses_to_the_pins_the_dev_lock_names() -> None:
    """Positive control on the real file: the comparator sees real pins."""
    pins, _ = mod.parse_lock((REPO_ROOT / "requirements.txt").read_text())
    assert len(pins) > 100


def test_run_as_a_script_without_the_repo_on_sys_path(tmp_path: Path) -> None:
    """The CI job runs `python scripts/ci/check_freeze_matches_lock.py` (sys.path[0]
    is scripts/ci, not the repo root): the sibling-import fallback must work."""
    lock = _write(tmp_path, "lock.txt", LOCK)
    fr = _write(tmp_path, "fr", GOOD)
    proc = subprocess.run(
        [
            sys.executable,
            str(REPO_ROOT / "scripts/ci/check_freeze_matches_lock.py"),
            "--lock",
            str(lock),
            "--freeze",
            str(fr),
        ],
        capture_output=True,
        text=True,
        cwd=tmp_path,
        check=False,
    )
    assert proc.returncode == 0, proc.stderr


def test_a_runner_python_without_packaging_falls_back_to_the_pips_vendored_copy(
    tmp_path: Path,
) -> None:
    """The e2e-compose job runs on a bare runner python. With `packaging` made
    unimportable the comparator must still work through pip's vendored copy.
    Neuter: delete the except-branch in check_venv_matches_lock -> RED."""
    lock = _write(tmp_path, "lock.txt", LOCK)
    fr = _write(tmp_path, "fr", GOOD)
    code = (
        "import runpy, sys\n"
        "for m in ('packaging', 'packaging.markers', 'packaging.utils'):\n"
        "    sys.modules[m] = None\n"
        "script, lock, freeze = sys.argv[1:4]\n"
        "sys.argv = [script, '--lock', lock, '--freeze', freeze]\n"
        "sys.path.insert(0, script.rsplit('/', 1)[0])\n"
        "runpy.run_path(script, run_name='__main__')\n"
    )
    script = str(REPO_ROOT / "scripts/ci/check_freeze_matches_lock.py")
    proc = subprocess.run(
        [sys.executable, "-c", code, script, str(lock), str(fr)],
        capture_output=True,
        text=True,
        cwd=tmp_path,
        check=False,
    )
    assert proc.returncode == 0, proc.stderr
